#!/usr/bin/env python3
# luxarch:worktree-git hook v1 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""How the worktree hook calls git: a literal-pathspec call on one checkout, with the variables that
point git at another repository removed, and a call to origin that cannot prompt or hang.

Python 3.9 and the standard library only, like the hook that loads it.
"""

from __future__ import annotations

import os
import subprocess
import tempfile
from pathlib import Path

# The variables that point git at a repository other than the one at `-C`. Exported (a session run
# from inside a git hook, a shell that set GIT_DIR), `--absolute-git-dir` in a worktree named the main
# checkout's git dir, and prune deleted the main checkout's submodule clones as the worktree's (v12).
GIT_LOCATION = (
    "GIT_DIR",
    "GIT_WORK_TREE",
    "GIT_COMMON_DIR",
    "GIT_INDEX_FILE",
    "GIT_OBJECT_DIRECTORY",
    "GIT_ALTERNATE_OBJECT_DIRECTORIES",
    "GIT_NAMESPACE",
    "GIT_CEILING_DIRECTORIES",
)


def git_env(**extra: str) -> dict[str, str]:
    env = {k: v for k, v in os.environ.items() if k not in GIT_LOCATION}
    env.update(extra)
    return env


def run(cwd: Path, *args: str) -> subprocess.CompletedProcess[str]:
    # every path handed to git is a literal path, never a pathspec: `ls-files -- :secret.env` read the
    # leading `:` as magic, so a file main tracks looked untracked and `land` deleted it (v5)
    return subprocess.run(
        ["git", "--literal-pathspecs", "-C", str(cwd), *args],
        capture_output=True,
        text=True,
        env=git_env(),
    )


def out(cwd: Path, *args: str) -> str:
    r = run(cwd, *args)
    return r.stdout.strip() if r.returncode == 0 else ""


def net_limit(push: bool) -> float:
    """Seconds a call to origin may take. A fetch or ls-remote gets `LUXARCH_LAND_TIMEOUT` (60 by
    default). A push gets `LUXARCH_LAND_PUSH_TIMEOUT` (1800 by default): it runs the repo's own
    pre-push hook, a secret scan of the whole history or an image build, which grows with the repo,
    and the fetch just before it has already shown that origin answers."""
    name, default = (
        ("LUXARCH_LAND_PUSH_TIMEOUT", 1800.0)
        if push
        else ("LUXARCH_LAND_TIMEOUT", 60.0)
    )
    try:
        return float(os.environ.get(name, default))
    except ValueError:
        return default


def run_net(
    cwd: Path, *args: str, push: bool = False
) -> subprocess.CompletedProcess[str]:
    """A git call that talks to origin: no terminal prompt, no stdin, and a timeout (`net_limit`), so
    an unanswering origin or a prompt reads as unreachable instead of hanging. The repo's own ssh
    settings (`core.sshCommand`) stay in force. git writes to files, not pipes, so the wait is for
    git itself: a process a pre-push hook leaves behind cannot hold the call open. git stays in this
    process's group, so an interrupt or a hangup stops it with `land`."""
    limit = net_limit(push)
    with tempfile.TemporaryFile() as o, tempfile.TemporaryFile() as e:
        try:
            r = subprocess.run(
                ["git", "--literal-pathspecs", "-C", str(cwd), *args],
                stdout=o,
                stderr=e,
                stdin=subprocess.DEVNULL,
                env=git_env(GIT_TERMINAL_PROMPT="0"),
                timeout=limit,
            )
        except subprocess.TimeoutExpired:
            # what git and its hooks printed before the limit says why they took so long
            o.seek(0)
            e.seek(0)
            said = (o.read() + e.read()).decode("utf-8", "replace").rstrip()
            return subprocess.CompletedProcess(
                args,
                124,
                "",
                (said + "\n" if said else "")
                + f"git {args[0]} did not answer within {limit:g}s",
            )
        o.seek(0)
        e.seek(0)
        return subprocess.CompletedProcess(
            args,
            r.returncode,
            o.read().decode("utf-8", "replace"),
            e.read().decode("utf-8", "replace"),
        )
